#pragma once
#include "share_control_profile131.hpp"
#include "resource_commands131.hpp"
namespace wht {
inline const ShareControlProfile131* ShareControlProfileFor131(unsigned build){for(const auto& p:shareControlProfiles131)if(p.build==build)return &p;return nullptr;}
inline bool ShareControlCode131(uintptr_t base,const ShareControlProfile131& p){ResourceTextProfile131 c{p.build,0,0,0,0,0,p.code,p.count};const auto* cp=ResourceCommandProfileFor131(p.build);return cp&&ResourceCommandCode131(base,*cp)&&ResourceTextGuard131(base,c);}
inline bool ParseShareControl131(const std::wstring& args,bool& enabled){if(args.find(L'\0')!=args.npos||args.find_first_of(L"\r\n")!=args.npos)return false;std::wistringstream in(args);std::wstring token,extra;enabled=true;if(in>>token){if((token!=L"0"&&token!=L"1")||in>>extra)return false;enabled=token==L"1";}return true;}
struct SharePeer131 {uintptr_t player=0;unsigned physical=24;};
struct ShareControlSnapshot131 {ResourceCommandSource131 source;uintptr_t alliance=0;uint32_t mask=0;std::array<SharePeer131,24> peers{};};
inline bool SameShareRoster131(const ShareControlSnapshot131& a,const ShareControlSnapshot131& b){if(!SameResourcePlayer131(a.source,b.source)||!a.alliance||a.alliance!=b.alliance)return false;for(unsigned i=0;i<24;++i)if(a.peers[i].player!=b.peers[i].player||a.peers[i].physical!=b.peers[i].physical)return false;return true;}
inline bool ReadShareControl131(uintptr_t base,unsigned build,ShareControlSnapshot131& out){const auto* sp=ShareControlProfileFor131(build);const auto* p=ResourceProfileFor131(build);if(!sp||!p||!ShareControlCode131(base,*sp))return false;ShareControlSnapshot131 v;if(!ReadResourceCommand131(base,build,v.source))return false;
 __try{v.alliance=*reinterpret_cast<uintptr_t*>(v.source.player+p->allianceOffset);if(!ResourceIdentity131(v.alliance,base,p->allianceTable))return false;v.mask=uint32_t(reinterpret_cast<int(__thiscall*)(uintptr_t)>(base+p->integerFn)(v.alliance+p->allianceMask+6*p->stateStride));const auto player=reinterpret_cast<uintptr_t(__thiscall*)(uintptr_t,unsigned)>(base+p->playerFn);uint32_t seen=1u<<v.source.physical;
 for(unsigned i=0;i<24;++i){const auto other=player(v.source.world,i);if(!other||other==v.source.player)continue;if(!ResourceIdentity131(other,base,p->playerTable))return false;if(*reinterpret_cast<int*>(other+p->statusOffset)!=1)continue;const unsigned id=*reinterpret_cast<unsigned char*>(other+p->idOffset);if(id>=24||(seen&(1u<<id)))return false;seen|=1u<<id;v.peers[i]={other,id};}
 ResourceCommandSource131 check;if(!ReadResourceCommand131(base,build,check)||!SameResourcePlayer131(v.source,check)||*reinterpret_cast<uintptr_t*>(v.source.player+p->allianceOffset)!=v.alliance||!ResourceIdentity131(v.alliance,base,p->allianceTable))return false;out=v;return true;}__except(1){return false;}}
using ShareControlNative131=void(__thiscall*)(uintptr_t,unsigned,unsigned);
inline bool InvokeShareControl131(ShareControlNative131 fn,uintptr_t alliance,unsigned physical){if(!fn||!alliance||physical>=24)return false;__try{fn(alliance,6,physical);return true;}__except(1){return false;}}
inline bool SetShareControlNative131(uintptr_t base,unsigned build,const ShareControlSnapshot131& expected,unsigned slot,bool enabled){if(slot>=24||!expected.peers[slot].player)return false;const auto* p=ShareControlProfileFor131(build);ShareControlSnapshot131 now;if(!p||!ReadShareControl131(base,build,now)||!SameShareRoster131(expected,now)||now.mask!=expected.mask)return false;return InvokeShareControl131(reinterpret_cast<ShareControlNative131>(base+(enabled?p->enable:p->disable)),now.alliance,now.peers[slot].physical);}
template<class Read,class Set> bool ShareControlFlow131(const std::wstring& args,Read read,Set set,std::string& report){bool enabled=true;if(!ParseShareControl131(args,enabled)){report="Usage: #shareall [0|1] (default ON)";return false;}ShareControlSnapshot131 original,current,after;if(!read(original)||!read(current)||!SameShareRoster131(original,current)||original.mask!=current.mask){report="Shared Control: stable active local player and roster required";return false;}unsigned changed=0;auto failure=[&](){report="Shared Control interrupted: "+std::to_string(changed)+" players confirmed; latest update may have applied";return false;};for(unsigned slot=0;slot<24;++slot){const auto peer=current.peers[slot];if(!peer.player)continue;if(peer.physical>=24||peer.player==current.source.player||peer.physical==current.source.physical)return failure();const uint32_t bit=1u<<peer.physical;if(bool(current.mask&bit)==enabled)continue;if(!read(after)||!SameShareRoster131(current,after)||current.mask!=after.mask)return failure();if(!set(after,slot,enabled))return failure();const uint32_t desired=enabled?current.mask|bit:current.mask&~bit;if(!read(after)||!SameShareRoster131(current,after)||after.mask!=desired)return failure();current=after;++changed;}report=std::string("Shared Control: ")+(enabled?"ON":"OFF")+" ("+std::to_string(changed)+" players changed; Local mode)";return true;}
inline bool ShareControlCommand131(uintptr_t base,unsigned build,const std::wstring& args,std::string& report){return ShareControlFlow131(args,[&](ShareControlSnapshot131& out){return ReadShareControl131(base,build,out);},[&](const ShareControlSnapshot131& v,unsigned slot,bool enabled){return SetShareControlNative131(base,build,v,slot,enabled);},report);}
}
